1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"os"
8		"strconv"
9		"unicode/utf8"
10	)
11	
12	// EvalReason is the machine-readable outcome of a flag evaluation.
13	type EvalReason string
14	
15	const (
16		EvalDisabled EvalReason = "disabled"
17		EvalRule     EvalReason = "rule"
18		EvalDefault  EvalReason = "default"
19	)
20	
21	// Condition is one predicate over an evaluation context.
22	type Condition struct {
23		Attribute string
24		Op        string
25		// strVal 用于 eq；inVal 用于 in（至少一项）。
26		strVal string
27		inVal  []string
28	}
29	
30	// Rule groups conditions that must all hold; on match the flag takes Value.
31	type Rule struct {
32		ID         string
33		Value      bool
34		Conditions []Condition
35	}
36	
37	// Flag is one feature toggle with its default and ordered rules.
38	type Flag struct {
39		Key     string
40		Enabled bool
41		Default bool
42		Rules   []Rule
43	}
44	
45	// Config is a validated feature flag configuration.
46	type Config struct {
47		Flags []Flag
48	}
49	
50	// EvalResult is the deterministic outcome of evaluating one flag.
51	type EvalResult struct {
52		Key    string     `json:"key"`
53		Value  bool       `json:"value"`
54		Reason EvalReason `json:"reason"`
55		RuleID *string    `json:"ruleId"`
56	}
57	
58	// Equals reports whether two evaluation results are identical.
59	func (r EvalResult) Equals(other EvalResult) bool {
60		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
61			return false
62		}
63		if (r.RuleID == nil) != (other.RuleID == nil) {
64			return false
65		}
66		if r.RuleID != nil && *r.RuleID != *other.RuleID {
67			return false
68		}
69		return true
70	}
71	
72	// Context is a validated map of attribute names to string values.
73	type Context struct {
74		values map[string]string
75	}
76	
77	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
78	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
79	func LoadConfig(path string) (*Config, error) {
80		raw, err := os.ReadFile(path)
81		if err != nil {
82			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
83		}
84		return ParseConfig(raw)
85	}
86	
87	// LoadContext reads and validates a UTF-8 JSON context file.
88	func LoadContext(path string) (*Context, error) {
89		raw, err := os.ReadFile(path)
90		if err != nil {
91			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
92		}
93		return ParseContext(raw)
94	}
95	
96	// ParseConfig parses a config document from JSON bytes with strict typing.
97	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
98	func ParseConfig(raw []byte) (*Config, error) {
99		if !utf8.Valid(raw) {
100			return nil, fmt.Errorf("config: file is not valid UTF-8")
101		}
102		if err := rejectDuplicateFields(raw, "config"); err != nil {
103			return nil, err
104		}
105		var doc any
106		if err := json.Unmarshal(raw, &doc); err != nil {
107			return nil, fmt.Errorf("config: invalid JSON: %w", err)
108		}
109		root, ok := doc.(map[string]any)
110		if !ok {
111			return nil, fmt.Errorf("config: top level must be a JSON object")
112		}
113		flagsRaw, present := root["flags"]
114		if !present {
115			return nil, fmt.Errorf("config.flags: field is required")
116		}
117		if flagsRaw == nil {
118			return nil, fmt.Errorf("config.flags: must be an array, got null")
119		}
120		flagsArr, ok := flagsRaw.([]any)
121		if !ok {
122			return nil, fmt.Errorf("config.flags: must be an array")
123		}
124		cfg := &Config{}
125		seenKeys := map[string]int{}
126		for i, fr := range flagsArr {
127			flag, err := parseFlag(fr, i)
128			if err != nil {
129				return nil, err
130			}
131			if prev, dup := seenKeys[flag.Key]; dup {
132				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
133			}
134			seenKeys[flag.Key] = i
135			cfg.Flags = append(cfg.Flags, flag)
136		}
137		return cfg, nil
138	}
139	
140	// ParseContext parses an attribute-name -> string context object; it may be empty.
141	func ParseContext(raw []byte) (*Context, error) {
142		if !utf8.Valid(raw) {
143			return nil, fmt.Errorf("context: file is not valid UTF-8")
144		}
145		if err := rejectDuplicateFields(raw, "context"); err != nil {
146			return nil, err
147		}
148		var doc any
149		if err := json.Unmarshal(raw, &doc); err != nil {
150			return nil, fmt.Errorf("context: invalid JSON: %w", err)
151		}
152		root, ok := doc.(map[string]any)
153		if !ok {
154			return nil, fmt.Errorf("context: top level must be a JSON object")
155		}
156		ctx := &Context{values: make(map[string]string, len(root))}
157		for k, v := range root {
158			s, ok := v.(string)
159			if !ok {
160				return nil, fmt.Errorf("context.%s: value must be a string", k)
161			}
162			ctx.values[k] = s
163		}
164		return ctx, nil
165	}
166	
167	// Get looks up an attribute; an empty string is a legal value.
168	func (c *Context) Get(attribute string) (string, bool) {
169		if c == nil {
170			return "", false
171		}
172		v, ok := c.values[attribute]
173		return v, ok
174	}
175	
176	// Find returns the flag with the given key, or nil if absent.
177	func (c *Config) Find(key string) *Flag {
178		if c == nil {
179			return nil
180		}
181		for i := range c.Flags {
182			if c.Flags[i].Key == key {
183				return &c.Flags[i]
184			}
185		}
186		return nil
187	}
188	
189	// Evaluate deterministically evaluates a flag against a context.
190	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
191	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
192	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
193	func (f *Flag) Evaluate(ctx *Context) EvalResult {
194		if !f.Enabled {
195			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
196		}
197		for i := range f.Rules {
198			rule := &f.Rules[i]
199			if rule.matches(ctx) {
200				id := rule.ID
201				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
202			}
203		}
204		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
205	}
206	
207	func (r *Rule) matches(ctx *Context) bool {
208		for i := range r.Conditions {
209			if !r.Conditions[i].matches(ctx) {
210				return false
211			}
212		}
213		return true
214	}
215	
216	func (c Condition) matches(ctx *Context) bool {
217		v, present := ctx.Get(c.Attribute)
218		if !present {
219			return false
220		}
221		switch c.Op {
222		case "eq":
223			return v == c.strVal
224		case "in":
225			for _, candidate := range c.inVal {
226				if v == candidate {
227					return true
228				}
229			}
230			return false
231		default:
232			// 解析阶段已拒绝未知运算符，防御性处理。
233			return false
234		}
235	}
236	
237	// MarshalResult renders the result as a single compact JSON object.
238	func MarshalResult(r EvalResult) ([]byte, error) {
239		var buf bytes.Buffer
240		enc := json.NewEncoder(&buf)
241		enc.SetEscapeHTML(false)
242		if err := enc.Encode(r); err != nil {
243			return nil, err
244		}
245		return bytes.TrimRight(buf.Bytes(), "\n"), nil
246	}
247	
248	// --- strict parsing helpers -------------------------------------------------
249	
250	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
251	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
252	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
253	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
254	// 前缀（"config" 或 "context"）。JSON 语法错误不在此报告，留给 Unmarshal。
255	func rejectDuplicateFields(raw []byte, label string) error {
256		dec := json.NewDecoder(bytes.NewReader(raw))
257		type frame struct {
258			path      string
259			object    bool
260			keys      map[string]struct{}
261			lastKey   string
262			expectKey bool
263			nextIndex int
264		}
265		var stack []*frame
266		// valueDone 在栈顶容器完成一个值（对象的一个字段值或数组的一个元素）后调用。
267		valueDone := func() {
268			if len(stack) == 0 {
269				return
270			}
271			top := stack[len(stack)-1]
272			if top.object {
273				top.expectKey = true
274			} else {
275				top.nextIndex++
276			}
277		}
278		childPath := func() string {
279			top := stack[len(stack)-1]
280			if top.object {
281				return top.path + "." + top.lastKey
282			}
283			return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
284		}
285		for {
286			tok, err := dec.Token()
287			if err != nil {
288				// io.EOF 或语法错误；语法错误由后续 Unmarshal 报告。
289				break
290			}
291			switch t := tok.(type) {
292			case json.Delim:
293				switch t {
294				case '{', '[':
295					path := label
296					if len(stack) > 0 {
297						path = childPath()
298					}
299					f := &frame{path: path, object: t == '{', expectKey: true}
300					if f.object {
301						f.keys = make(map[string]struct{})
302					}
303					stack = append(stack, f)
304				case '}', ']':
305					stack = stack[:len(stack)-1]
306					valueDone()
307				}
308			case string:
309				if len(stack) > 0 && stack[len(stack)-1].object && stack[len(stack)-1].expectKey {
310					top := stack[len(stack)-1]
311					if _, dup := top.keys[t]; dup {
312						return fmt.Errorf("%s.%s: duplicate field %q", top.path, t, t)
313					}
314					top.keys[t] = struct{}{}
315					top.lastKey = t
316					top.expectKey = false
317				} else {
318					valueDone()
319				}
320			default:
321				valueDone()
322			}
323		}
324		return nil
325	}
326	
327	func parseFlag(raw any, index int) (Flag, error) {
328		loc := fmt.Sprintf("config.flags[%d]", index)
329		obj, ok := raw.(map[string]any)
330		if !ok {
331			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
332		}
333		key, err := requireNonEmptyString(obj, "key", loc)
334		if err != nil {
335			return Flag{}, err
336		}
337		enabled, err := requireBool(obj, "enabled", loc)
338		if err != nil {
339			return Flag{}, err
340		}
341		def, err := requireBool(obj, "default", loc)
342		if err != nil {
343			return Flag{}, err
344		}
345		rulesArr, err := requireArrayField(obj, "rules", loc)
346		if err != nil {
347			return Flag{}, err
348		}
349		flag := Flag{Key: key, Enabled: enabled, Default: def}
350		seenRules := map[string]int{}
351		for ri, rv := range rulesArr {
352			rule, err := parseRule(rv, index, ri)
353			if err != nil {
354				return Flag{}, err
355			}
356			if prev, dup := seenRules[rule.ID]; dup {
357				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
358			}
359			seenRules[rule.ID] = ri
360			flag.Rules = append(flag.Rules, rule)
361		}
362		return flag, nil
363	}
364	
365	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
366		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
367		obj, ok := raw.(map[string]any)
368		if !ok {
369			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
370		}
371		id, err := requireNonEmptyString(obj, "id", loc)
372		if err != nil {
373			return Rule{}, err
374		}
375		value, err := requireBool(obj, "value", loc)
376		if err != nil {
377			return Rule{}, err
378		}
379		condsArr, err := requireArrayField(obj, "conditions", loc)
380		if err != nil {
381			return Rule{}, err
382		}
383		if len(condsArr) == 0 {
384			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
385		}
386		rule := Rule{ID: id, Value: value}
387		for ci, cv := range condsArr {
388			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
389			if err != nil {
390				return Rule{}, err
391			}
392			rule.Conditions = append(rule.Conditions, cond)
393		}
394		return rule, nil
395	}
396	
397	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
398		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
399		obj, ok := raw.(map[string]any)
400		if !ok {
401			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
402		}
403		attribute, err := requireNonEmptyString(obj, "attribute", loc)
404		if err != nil {
405			return Condition{}, err
406		}
407		op, err := requireNonEmptyString(obj, "op", loc)
408		if err != nil {
409			return Condition{}, err
410		}
411		valueField, err := requireField(obj, "value", loc)
412		if err != nil {
413			return Condition{}, err
414		}
415		cond := Condition{Attribute: attribute, Op: op}
416		switch op {
417		case "eq":
418			s, ok := valueField.(string)
419			if !ok {
420				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
421			}
422			cond.strVal = s
423		case "in":
424			arr, ok := valueField.([]any)
425			if !ok {
426				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
427			}
428			if len(arr) == 0 {
429				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
430			}
431			for ii, item := range arr {
432				s, ok := item.(string)
433				if !ok {
434					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
435				}
436				cond.inVal = append(cond.inVal, s)
437			}
438		default:
439			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
440		}
441		return cond, nil
442	}
443	
444	func requireField(obj map[string]any, name, loc string) (any, error) {
445		v, ok := obj[name]
446		if !ok {
447			return nil, fmt.Errorf("%s.%s: field is required", loc, name)
448		}
449		if v == nil {
450			return nil, fmt.Errorf("%s.%s: must not be null", loc, name)
451		}
452		return v, nil
453	}
454	
455	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
456		v, err := requireField(obj, name, loc)
457		if err != nil {
458			return nil, err
459		}
460		arr, ok := v.([]any)
461		if !ok {
462			return nil, fmt.Errorf("%s.%s: must be an array", loc, name)
463		}
464		return arr, nil
465	}
466	
467	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
468		v, err := requireField(obj, name, loc)
469		if err != nil {
470			return "", err
471		}
472		s, ok := v.(string)
473		if !ok {
474			return "", fmt.Errorf("%s.%s: must be a string", loc, name)
475		}
476		if s == "" {
477			return "", fmt.Errorf("%s.%s: must not be empty", loc, name)
478		}
479		return s, nil
480	}
481	
482	func requireBool(obj map[string]any, name, loc string) (bool, error) {
483		v, err := requireField(obj, name, loc)
484		if err != nil {
485			return false, err
486		}
487		b, ok := v.(bool)
488		if !ok {
489			return false, fmt.Errorf("%s.%s: must be a boolean", loc, name)
490		}
491		return b, nil
492	}
