func TestInvalidUnicodeEscapesRejected(t *testing.T) {
	// encoding/json 会把孤立代理项转义静默替换为 U+FFFD；这些输入必须明确失败，
	// 且错误指出文件（config/context）、字段或数组位置，并说明转义不能组成完整字符。
